public static double roundHalfToEven(double n) {
    // If the number is an integer, return it
    if (n == (int)n) return n;

    // Get the absolute value of the number
    double abs = Math.abs(n);

    // Get the fractional part of the number
    double fraction = abs - (int)abs;

    // If the fractional part is greater than 0.5, round up to the next even number
    if (fraction > 0.5) return (int)n + 1;

    // If the fractional part is less than 0.5, round down to the previous even number
    if (fraction < 0.5) return (int)n - 1;

    // If the fractional part is 0.5, round to the nearest even number
    return (int)n % 2 == 0 ? n : n - fraction;
}
