public static List<String> normalizeCmd(List<String> cmd) {
    // Fixes for the following issues on Windows
    // - https://bugs.python.org/issue8557
    // - Windows does not parse shebangs

    //Make deep-path shebangs work just fine

    //First, remove any in-place modifications
    for (String s: cmd) {
        if (s.contains("&")) {
            s = s.replace("&", "");
        }
    }

    //Next, fix any deep-path shebangs
    StringBuffer sb = new StringBuffer();
    for (String s: cmd) {
        if (s.contains("/") && !s.startsWith("/")) {
            sb.append(s);
            if (!s.endsWith("/")) {
                sb.append('/');
            }
        }
    }
    return sb.toString().split(" ");
