  //Check if the version is in the format of major.minor.patch
  if (version.split(".").length === 3) {
    //Get the major, minor, and patch version numbers
    let [major, minor, patch] = version.split(".");

    //Increment the patch version number
    patch = Number(patch) + 1;

    //Check if the patch version number is 100 or more
    if (patch >= 100) {
      //Increment the minor version number
      minor = Number(minor) + 1;

      //Reset the patch version number to 0
      patch = 0;
    }

    //Check if the minor version number is 100 or more
    if (minor >= 100) {
      //Increment the major version number
      major = Number(major) + 1;

      //Reset the minor and patch version numbers to 0
      minor = 0;
      patch = 0;
    }

    //Return the next version identifier
    return `${major}.${minor}.${patch}`;
  } else {
    //Handle the case where the version is not in the correct format
    return "Invalid version format";
  }
}

