      }
    }
  }

  // Check if the candidate defines all the necessary attributes
  const attrs = iface.attributes;
  for (const attr of attrs) {
    if (typeof candidate[attr] === 'undefined') {
      throw new Error(`The candidate does not define the attribute "${attr}"`);
    }
  }

  // Return true if all the conditions are met
  return true;
}

