public static String processTextLinks(String text) {

    // Find all link text and URLs in the text
    Pattern pattern = Pattern.compile("\\[([^\\[]+)\\]\\(([^\\)]+)\\)");
    Matcher matcher = pattern.matcher(text);

    // Create a Spannable to edit the text
    Spannable spannable = new SpannableString(text);

    // Iterate over the matches and add attributes and linkify the text
    while (matcher.find()) {
        String linkText = matcher.group(1);
        String linkUrl = matcher.group(2);

        // Add a URLSpan to the link text
        int start = matcher.start(1);
        int end = matcher.end(1);
        URLSpan urlSpan = new URLSpan(linkUrl);
        spannable.setSpan(urlSpan, start, end,
                    Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);

        // Add a StyleSpan to make the link text blue and underlined
        start = matcher.start(1);
        end = matcher.end(1);
        StyleSpan blueUnderlined = new StyleSpan(android.graphics.Typeface.BOLD);
        spannable.setSpan(blueUnderlined, start, end,
                    Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);
    }

    return spannable;
