def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The parser dictionary containing the include directive.

    Returns:
        dict: The parsed dictionary with the included files.
    """
    include_directive = 'include'
    group_directive = 'group'
    excluded_directive = 'exclude'

    include_groups = set()
    excluded_groups = set()

    for key, value in parser_dict.items():
        if key == include_directive:
            include_groups = set(value.split(','))
        elif key == group_directive:
            include_groups.add(value)
        elif key == excluded_directive:
            excluded_groups.add(value)

    included_groups = include_groups - excluded_groups
    included_groups = [g.strip() for g in included_groups]

    if not included_groups:
        raise ValueError('No groups specified in the include directive.')

    for group in included_groups:
        if group not in parser_dict:
            raise KeyError(f'Group {group} not found in the parser dictionary.')

    return {group: parser_dict[group] for group in included_groups}

