public class AnsiblePlaybook{
private static void ansible_playbook(IrWorkspace ir_workspace, IrPlugin ir_plugin,
                String playbookPath,  Integer verbose, Map<String, String> extraVars, String[] ansibleArgs) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder("ansible-playbook", playbookPath);

        pb.directory(ir_workspace.workspaceRoot.toFile());

        if (extraVars != null) {
            for (Map.Entry<String, String> entry : extraVars.entrySet()) {
                pb.environment().put(entry.getKey(), entry.getValue());
            }
        }

        if (ansibleArgs != null) {
            pb.command().addAll(Arrays.asList(ansibleArgs));
        }

        if (verbose != null) {
            pb.redirectErrorStream(true);
            Process process = pb.start();
            process.waitFor();
            System.out.println(process.getInputStream());
        }
}
}

